import { build } from "esbuild";

await build({
    entryPoints: ["src/index.ts"],
    format: "esm",
    platform: "browser",
    bundle: true,
    sourcemap: true,
    minify: true,
    external: ["react"],
    define: {
        "process.env.NODE_ENV": '"production"',
    },
    tsconfig: "tsconfig.base.json",
    outdir: "dist/esm-browser.min/",
    outbase: "src",
})
